CREATE COLUMN TABLE "TEST_AP"."@DEPARTMENT_ADD" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_DeptName" NVARCHAR(50), "U_Description" NVARCHAR(100), "U_Function" NVARCHAR(100), "U_CostCenter" NVARCHAR(20), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KDEPARTMENT_ADD_NAME" ON "TEST_AP"."@DEPARTMENT_ADD" ( "Name" ASC )